/// <summary>
/// find()
/// </summary>
/// <param name = "_salesId">SalesId</param>
/// <param name = "_forupdate">boolean</param>
/// <returns>KCS_SOCSalesTableInfoFields</returns>
public static KCS_SOCSalesTableInfoFields find(AVATableInfoFieldTypes   _infoType,
                                               Salesid                  _salesId, 
                                               boolean                  _forupdate = false)
{
    KCS_SOCSalesTableInfoFields   salesTableInfoFields;

    salesTableInfoFields.selectForUpdate(_forupdate);

    select firstonly salesTableInfoFields 
        where salesTableInfoFields.InfoType == _infoType
           && salesTableInfoFields.SalesId  == _salesId;

    return salesTableInfoFields;
}

/// <summary>
/// exist
/// </summary>
/// <param name = "_salesId">SalesId</param>
/// <returns>boolean</returns>
static boolean exist(AVATableInfoFieldTypes _infoType,
                     Salesid                _salesId)
{
    KCS_SOCSalesTableInfoFields   salesTableInfoFields;

    select firstonly salesTableInfoFields 
        where salesTableInfoFields.InfoType == _infoType
           && salesTableInfoFields.SalesId == _salesId;

    return salesTableInfoFields.RecId;
}

public void initInfoFields(Common _record)
{
    switch (_record.TableId)
    {
        case tableNum(SalesTable):
            this.initInfoFieldsFromSalesTable(_record);
            break;
        case tableNum(InventTransferTable):
            this.initInfoFieldsFromInventTransferTable(_record);
            break;
        default:
            throw error(Error::wrongUseOfFunction(funcName()));
    }
}

