public void initInfoFieldsFromInventTransferTable(InventTransferTable _inventTransferTable)
{
    KCS_SOCSalesTableInfoFields salesTableInfoFields;

    salesTableInfoFields = KCS_SOCSalesTableInfoFields::find(AVATableInfoFieldTypes::Sales, _inventTransferTable.TransferId);

    if (!salesTableInfoFields)
    {
        ttsBegin;
        this.clear();
        this.SalesId    = _inventTransferTable.TransferId;
        this.InfoType   = AVATableInfoFieldTypes::TransferOrderShip;
        this.insert();
        ttsCommit;
    }
}

/// <summary>
///modifiedField
/// </summary>
/// <param name = "_fieldId">FieldId</param>
public void modifiedField(FieldId _fieldId)
{
    super(_fieldId);

    switch (_fieldId)
    {
        case fieldNum(KCS_HDMSalesQuotationTableInfoFields, InfoField2Finished):
            this.InfoField2FinishedUser         = curUserId();
            this.InfoField2FinishedDateTime     = DateTimeUtil::getSystemDateTime();
            break;
    }

}
